CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN ('admin','production')), password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, actor TEXT NOT NULL, csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS templates(id TEXT PRIMARY KEY, doc TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS calibrations(template_id TEXT NOT NULL, profile_id TEXT NOT NULL, doc TEXT NOT NULL, PRIMARY KEY(template_id, profile_id));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, revision INTEGER NOT NULL DEFAULT 1, doc TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS groups(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), template_id TEXT NOT NULL REFERENCES templates(id), doc TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recipients(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), group_id TEXT NOT NULL REFERENCES groups(id), revision INTEGER NOT NULL, doc TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recipient_revisions(id INTEGER PRIMARY KEY AUTOINCREMENT, recipient_id TEXT NOT NULL, revision INTEGER NOT NULL, doc TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), recipient_id TEXT NOT NULL REFERENCES recipients(id), upload_id TEXT NOT NULL, sha256 TEXT NOT NULL, doc TEXT NOT NULL, UNIQUE(recipient_id,upload_id));
CREATE TABLE IF NOT EXISTS links(id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, order_id TEXT NOT NULL REFERENCES orders(id), role TEXT NOT NULL, group_id TEXT, expires_at INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS proofs(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), recipient_id TEXT NOT NULL REFERENCES recipients(id), revision INTEGER NOT NULL, doc TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), revision INTEGER NOT NULL, doc TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), kind TEXT NOT NULL, status TEXT NOT NULL, payload TEXT NOT NULL, result TEXT, error TEXT, attempts INTEGER NOT NULL DEFAULT 0, progress REAL NOT NULL DEFAULT 0, priority INTEGER NOT NULL DEFAULT 10, available_at INTEGER NOT NULL DEFAULT 0, locked_until INTEGER NOT NULL DEFAULT 0, owner TEXT, cancelled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS print_jobs(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), approval_id TEXT NOT NULL REFERENCES approvals(id), revision INTEGER NOT NULL, status TEXT NOT NULL, doc TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT, order_id TEXT, actor TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS recipient_order_idx ON recipients(order_id);
CREATE INDEX IF NOT EXISTS jobs_claim_idx ON jobs(status, available_at, priority);
CREATE INDEX IF NOT EXISTS assets_order_idx ON assets(order_id);
INSERT OR IGNORE INTO schema_migrations VALUES(1,datetime('now'));
